def bowling_score(rolls: list[int]) -> int:
    # Basic validation: all rolls must be integers between 0 and 10
    if not isinstance(rolls, list):
        raise ValueError("Rolls must be a list of integers.")
    for r in rolls:
        if not isinstance(r, int) or r < 0 or r > 10:
            raise ValueError("Each roll must be an integer between 0 and 10.")

    total_score = 0
    roll_idx = 0
    n = len(rolls)

    # Process frames 1 through 9
    for frame in range(1, 10):
        if roll_idx >= n:
            raise ValueError("Too few rolls for a complete game.")

        # Strike
        if rolls[roll_idx] == 10:
            if roll_idx + 2 >= n:
                raise ValueError("Too few rolls for strike bonus.")
            # Check validity of two bonus rolls if they are not consecutive strikes
            if rolls[roll_idx + 1] != 10 and rolls[roll_idx + 1] + rolls[roll_idx + 2] > 10:
                raise ValueError("Bonus rolls exceed 10 pins.")
            total_score += 10 + rolls[roll_idx + 1] + rolls[roll_idx + 2]
            roll_idx += 1
        else:
            # Not a strike, frame requires two rolls
            if roll_idx + 1 >= n:
                raise ValueError("Too few rolls for frame.")
            first = rolls[roll_idx]
            second = rolls[roll_idx + 1]
            if first + second > 10:
                raise ValueError("Frame total cannot exceed 10.")

            # Spare
            if first + second == 10:
                if roll_idx + 2 >= n:
                    raise ValueError("Too few rolls for spare bonus.")
                total_score += 10 + rolls[roll_idx + 2]
            else:
                # Open frame
                total_score += first + second
            roll_idx += 2

    # Process 10th frame
    if roll_idx >= n:
        raise ValueError("Too few rolls for 10th frame.")

    first = rolls[roll_idx]
    if first == 10:
        # Strike in 10th frame requires 2 bonus rolls (3 rolls total in 10th frame)
        if roll_idx + 2 >= n:
            raise ValueError("Too few rolls for 10th frame strike.")
        second = rolls[roll_idx + 1]
        third = rolls[roll_idx + 2]
        if second != 10 and second + third > 10:
            raise ValueError("Bonus rolls exceed 10 pins in 10th frame.")
        total_score += 10 + second + third
        roll_idx += 3
    else:
        if roll_idx + 1 >= n:
            raise ValueError("Too few rolls for 10th frame.")
        second = rolls[roll_idx + 1]
        if first + second > 10:
            raise ValueError("10th frame rolls exceed 10 pins.")

        if first + second == 10:
            # Spare in 10th frame requires 1 bonus roll (3 rolls total in 10th frame)
            if roll_idx + 2 >= n:
                raise ValueError("Too few rolls for 10th frame spare bonus.")
            third = rolls[roll_idx + 2]
            total_score += 10 + third
            roll_idx += 3
        else:
            # Open 10th frame requires exactly 2 rolls
            total_score += first + second
            roll_idx += 2

    # Check for any extra unexpected rolls
    if roll_idx != n:
        raise ValueError("Too many rolls for a complete game.")

    return total_score
